const{execSync}=require("child_process");
let output;
try{output=execSync("systemctl --user list-units jarvis-* --no-pager --plain 2>/dev/null || systemctl list-units jarvis-* --no-pager --plain 2>/dev/null",{encoding:"utf-8",timeout:15000});}catch(e){output=e.stdout||"";}
const lines=output.split("\n").filter(l=>l.trim()&&!l.startsWith("UNIT")&&!l.includes("listed")&&!l.includes("To show"));
const services=[];const failed=[];
for(const line of lines){const parts=line.trim().split(/\s+/);if(parts.length>=4){const svc={unit:parts[0],load:parts[1],active:parts[2],sub:parts[3]};services.push(svc);if(svc.active==="failed"||svc.sub==="failed"){failed.push(svc);}}}
return[{json:{probe:"systemd",services,failed,hasFailed:failed.length>0,checkedAt:new Date().toISOString()}}];

const{execSync}=require("child_process");
let raw="";
try{raw=execSync("nvidia-smi --query-gpu=index,name,temperature.gpu,utilization.gpu,memory.used,memory.total,power.draw --format=csv,noheader,nounits 2>/dev/null || echo GPU_ERROR",{encoding:"utf-8",timeout:15000});}catch(e){raw=e.stdout||"GPU_ERROR";}
if(raw.includes("GPU_ERROR")||!raw.trim()){return[{json:{probe:"gpu",error:true,gpus:[],criticals:[],alert:false,checkedAt:new Date().toISOString()}}];}
const gpus=raw.trim().split("\n").map((line,i)=>{const p=line.split(",").map(s=>s.trim());return{index:parseInt(p[0])||i,name:p[1]||"GPU",temp:parseInt(p[2])||0,gpu_util:parseInt(p[3])||0,mem_used:parseInt(p[4])||0,mem_total:parseInt(p[5])||0,power:parseFloat(p[6])||0};});
const criticals=gpus.filter(g=>g.temp>=85);
return[{json:{probe:"gpu",gpus,criticals,alert:criticals.length>0,checkedAt:new Date().toISOString()}}];

const{execSync}=require("child_process");
const freeOutput=execSync("free -m",{encoding:"utf-8",timeout:10000});
const lines=freeOutput.trim().split("\n");
const memLine=lines[1].split(/\s+/);
const totalRAM=parseInt(memLine[1]);
const usedRAM=parseInt(memLine[2]);
const availRAM=parseInt(memLine[6]);
const ramPct=Math.round((usedRAM/totalRAM)*100);
let swapInfo={devices:[],zramActive:false};
try{const swapOutput=execSync("swapon --show --noheadings --bytes 2>/dev/null",{encoding:"utf-8",timeout:10000});const swapLines=swapOutput.trim().split("\n").filter(l=>l.trim());swapInfo.devices=swapLines.map(l=>{const p=l.split(/\s+/);return{name:p[0],type:p[1],size:p[2],used:p[3]};});swapInfo.zramActive=swapLines.some(l=>l.includes("zram"));}catch(e){}
const swapLine=lines.find(l=>l.startsWith("Swap"));
let swapTotal=0,swapUsed=0;
if(swapLine){const sp=swapLine.split(/\s+/);swapTotal=parseInt(sp[1]);swapUsed=parseInt(sp[2]);}
return[{json:{probe:"memory",totalRAM,usedRAM,availRAM,ramPct,swapTotal,swapUsed,swap:swapInfo,isWarning:ramPct>90,checkedAt:new Date().toISOString()}}];

// Agrégation robuste sans dépendance aux ports du Merge.
// Référence explicite chaque probe amont et renvoie 1 item par probe
// (équivalent fonctionnel d'un Merge combineAll en aval).
function grab(name){try{const r=$(name).all();return (r||[]).map(i=>i.json).filter(Boolean);}catch(e){return[];}}
const out=[];
for(const j of grab("Probe Systemd Units")){out.push(j);}
for(const j of grab("Probe GPU Thermal")){out.push(j);}
for(const j of grab("Probe ZRAM & Memory")){out.push(j);}
if(out.length===0){out.push({probe:"none",error:true,note:"no upstream probe items"});}
return out.map(json=>({json}));

const items=$input.all().map(i=>i.json);
const byProbe={};
for(const it of items){if(it&&it.probe){byProbe[it.probe]=it;}}
const sys=byProbe.systemd||{};
const gpu=byProbe.gpu||{};
const mem=byProbe.memory||{};
const alerts=[];
if(sys.hasFailed){alerts.push(`SYSTEMD: ${(sys.failed||[]).map(s=>s.unit).join(", ")}`);}
if(gpu.alert){alerts.push(`GPU: ${(gpu.criticals||[]).map(g=>`GPU${g.index} ${g.temp}C`).join(", ")}`);}
if(mem.isWarning){alerts.push(`RAM: ${mem.ramPct}% (${mem.usedRAM}/${mem.totalRAM}MB)`);}
const level=alerts.length===0?"ok":(gpu.alert||sys.hasFailed)?"critical":"warning";
const summary={
  source:"sub-monitoring",
  level,
  alertCount:alerts.length,
  alerts,
  probes:{
    systemd:{failed:(sys.failed||[]).length,total:(sys.services||[]).length},
    gpu:{criticals:(gpu.criticals||[]).length,gpus:(gpu.gpus||[]).length,error:!!gpu.error},
    memory:{ramPct:mem.ramPct||null,zramActive:mem.swap?mem.swap.zramActive:null}
  },
  message:alerts.length?`JARVIS MONITOR [${level.toUpperCase()}]: ${alerts.join(" | ")}`:"JARVIS MONITOR: all probes nominal",
  checkedAt:new Date().toISOString()
};
return[{json:summary}];
